entries[89890] = { ["name"] = "Eerie Smolderthorn Idol", ["text"] = "2 sec cast 5\nWhen the high elves went to war with the Amani trolls, the elves could not understand how the trolls' weapon enchantments were more powerful than their own. The elves then stole ancient knowledge from troll spellcasters, including the famous Zanza, and used idols such as this one to craft their own versions of the troll enchantments.\nEerie Smolderthorn Idol\nBinds when picked up" }
entries[89891] = { ["name"] = "Cinnabar Bijou", ["text"] = "2 sec cast 5\nThis small token was formed from a volcanic - and toxic - red mineral. The inscription on the reverse states that it was once the property of Min'loth the Serpent. Traces of barnacles suggest that the bijou has spent time underwater.\nCinnabar Bijou\nBinds when picked up" }
entries[89892] = { ["name"] = "Throw Bomb", ["text"] = "15 yd range\nInstant\nThrow a bomb at a nearby oil gusher to ignite it." }
entries[89893] = { ["name"] = "Coin from Eldre'Thalas", ["text"] = "2 sec cast 5\nOnce a Highborne capital, the city of Queen Azshara's arcanists fell into decay and ultimately depravity following the Great Sundering. The ruin is now known as Dire Maul.\nCoin from Eldre'Thalas\nBinds when picked up" }
entries[89894] = { ["name"] = "Shattered Glaive", ["text"] = "2 sec cast 5\nThis is a fragment of a large, three-bladed projectile fired from elven siege weapons. While glaive throwers are common even today, this fragment is of an ancient design with detailed ornamentation, even by night elf standards.\nShattered Glaive\nBinds when picked up" }
entries[89895] = { ["name"] = "Twisted Ammonite Shell", ["text"] = "2 sec cast 5\nAmmonites are an extinct type of shelled squid. The shell could be long like a spear or coiled in a variety of different ways. While this fossil is of a small specimen, they could grow quite large.\nTwisted Ammonite Shell\nBinds when picked up" }
entries[89896] = { ["name"] = "Green Dragon Ring", ["text"] = "2 sec cast 5\nThis is likely a representation of Eranikus, consort of Ysera. Eranikus was lost to the corruption of the Emerald Nightmare and later redeemed. Along the inside of the ring is inscribed, 'Andu-falah-dor!'\nGreen Dragon Ring\nBinds when picked up" }
