entries[90427] = { ["name"] = "Carried by Cromush" }
entries[90428] = { ["name"] = "Reverse Cast Ride" }
entries[90429] = { ["name"] = "Atal'ai Scepter", ["text"] = "2 sec cast 5\n'Atal'ai' means 'devoted ones' in Zandali, and this twisted group of trolls was devoted to the blood god, Hakkar: a being of extreme malevelonce who recently tasted defeat in Zul'Gurub, ancient capital of the Gurubashi empire. This scepter is decorated with a bat motif, possibly a connection to Hir'eek, the primal bat god.\nAtal'ai Scepter\nBinds when picked up" }
entries[90430] = { ["name"] = "Kill Credit" }
entries[90431] = { ["name"] = "See Quest Invis 7" }
entries[90432] = { ["name"] = "Devilsaur Tooth", ["text"] = "2 sec cast 5\nDevilsaurs are among the largest predators to ever walk Azeroth. While most died out long ago, some thrive in isolated pockets to this day. There is much speculation about the purpose of the devilsaur's degenerate front arms. One theory is that they help devilsaurs rise to a standing position; another theory suggests that the arms titillate females. More observation is necessary.\nDevilsaur Tooth\nBinds when picked up" }
entries[90433] = { ["name"] = "Insect in Amber", ["text"] = "2 sec cast 5\nAmber is petrified tree resin. One of the purposes of tree resin is to defend the tree from attacking insects, so very rare hunks of amber may contain preserved insects within.\nInsect in Amber\nBinds when picked up" }
