entries[90451] = { ["name"] = "Kaldorei Amphora", ["text"] = "2 sec cast 5\nThis slender vase with two looping handles was used to mix or store Darnassian wine. Even after all this time, you can still detect a faint scent of ginger from the dried residue at the bottom of this vessel.\nKaldorei Amphora\nBinds when picked up" }
entries[90452] = { ["name"] = "Ancient Shark Jaws", ["text"] = "2 sec cast 5\nSharks have no true bones, only cartilage. Because their feeding habits involve biting things with a great deal of force, losing teeth is common. Therefore, sharks have multiple rows of teeth which they replace constantly throughout their lifetimes.\nAncient Shark Jaws\nBinds when picked up" }
entries[90453] = { ["name"] = "Hairpin of Silver and Malachite", ["text"] = "2 sec cast 5\nEngraved beneath the setting for the precious stone are the words 'To Theleste, on her twenty-fourth birth year.'\nHairpin of Silver and Malachite\nBinds when picked up" }
