entries[90499] = { ["name"] = "Item - Shaman T11 Restoration 4P Bonus", ["text"] = "Grants 540 Intellect for 6 sec after you cast Riptide." }
entries[90501] = { ["name"] = "Item - Shaman T11 Enhancement 2P Bonus", ["text"] = "Increases damage done by your Lava Lash and Stormstrike abilities by 10%." }
entries[90502] = { ["name"] = "Item - Shaman T11 Enhancment 4P Bonus", ["text"] = "Increases the critical strike chance of your Lightning Bolt spell by 10%." }
entries[90503] = { ["name"] = "Item - Shaman T11 Elemental 2P Bonus", ["text"] = "Increases the critical strike chance of your Flame Shock spell by 10%." }
entries[90504] = { ["name"] = "Dented Shield of Horuz Killcrow", ["text"] = "2 sec cast 5\nThe grave mistake made by Horuz when he and his companions fought the great wyrm Kaldrigos cost the storied warrior his life. He stood directly behind the dragon. Never do that.\nDented Shield of Horuz Killcrow\nBinds when picked up" }
entries[90505] = { ["name"] = "Item - Shaman T11 Elemental 4P Bonus", ["text"] = "Reduces the cast time of your Lightning Bolt spell by 10%." }
entries[90506] = { ["name"] = "Scorched Staff of Shadow Priest Anund", ["text"] = "2 sec cast 5\nThis wooden staff has been thoroughly blackened by arcane breath. Such was the fate of its wielder as well.\nScorched Staff of Shadow Priest Anund\nBinds when picked up" }
entries[90507] = { ["name"] = "Death Eater", ["text"] = "Instant\nEach time you gain a Death Rune, you also gain 1% increased attack power for 30 sec. Stacks up to 3 times." }
entries[90508] = { ["name"] = "Burning Steppes Guardian Aura (H)" }
entries[90509] = { ["name"] = "Scepter of Charlga Razorflank", ["text"] = "2 sec cast 5\nAlthough these artifact fragments were found intermingled with those of dwarves, this scepter is clearly not of dwarven manufacture, but was made by quilboar. In fact, it was once wielded by Charlga Razorflank herself. Perhaps it came into dwarven possession when heroes attempted to conquer Razorfen Kraul.\nScepter of Charlga Razorflank\nBinds when picked up" }
entries[90510] = { ["name"] = "Quest Invisibility 25" }
entries[90511] = { ["name"] = "Invisibility Detection Quest 25" }
entries[90518] = { ["name"] = "Mithril Chain of Angerforge", ["text"] = "2 sec cast 5\nThe Angerforge family has a long lineage in Dark Iron dwarf history. This is a chain worn by Thane Angerforge, the ancestor of General Angerforge, who still commands the Dark Iron armies of Blackrock Depths.\nMithril Chain of Angerforge\nBinds when picked up" }
entries[90519] = { ["name"] = "Skull Staff of Shadowforge", ["text"] = "2 sec cast 5\nThe Shadowforge family has left a long stain on Dark Iron history. Iron Thane Shadowforge was by all accounts a cruel despot who tortured and killed many of his own people. While it is generally held that he was a warlock, some accounts cling to the rumor that he was one of the first dwarven shaman.\nSkull Staff of Shadowforge\nBinds when picked up" }
entries[90520] = { ["name"] = "Arcane Overload" }
entries[90521] = { ["name"] = "Clockwork Gnome", ["text"] = "2 sec cast 15\nMechagnomes were created by the titans, apparently as servants and caretakers, much like the earthen. This mechagnome was likely damaged because it is no longer focused on its original tasks and seems content to follow you.\nClockwork Gnome\nBinds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Clockwork Gnome.\n1 to 80 ( 80)" }
entries[90522] = { ["name"] = "Water Shell", ["text"] = "40 yd range\n2 sec cast\nAbsorbs 189 damage, if the Water Shell is broken, it wil explode and inflict 57 Frost damage to enemies within 8 yards." }
entries[90523] = { ["name"] = "Clockwork Gnome", ["text"] = "Instant\nRight Click to summon and dismiss your Clockwork Gnome." }
entries[90524] = { ["name"] = "Water Explosion", ["text"] = "40 yd range\nInstant\nInflicts 57 Frost damage to enemies within 8 yards." }
entries[90528] = { ["name"] = "See Quest Invis 5" }
entries[90546] = { ["name"] = "Oafguard", ["text"] = "Instant\nProtected by a mighty Oaf. Helix cannot die while his Oaf lumbers on." }
entries[90550] = { ["name"] = "Arcane Barrage", ["text"] = "100 Mana 30 yd range\n2 sec cast\nLaunches several missiles at the enemy target, inflicting Arcane damage." }
entries[90551] = { ["name"] = "Overwhelming Power", ["text"] = "100 yd range\n5 sec cast\nSends out an arc of magic, inflicting Arcane damage to the target enemy." }
entries[90553] = { ["name"] = "Chalice of the Mountain Kings", ["text"] = "2 sec cast 15\nIn addition to the many jewels adorning it, this chalice is virtually covered with runes celebrating an old ascension ceremony for dwarven kings. Drinking from this chalice was certainly a part of it, but the runes go on to describe a 'sword dance' done by female dwarven warriors. This performance, part ritual and part mock battle, apparently evolved from bloody duels fought during less sophisticated times in dwarven history.\nChalice of the Mountain Kings\nBinds when picked up\nToy\nUse: Witness a historic sword dance. (10 Min Cooldown)" }
